import{_ as s,C as n,o as r,c as i,j as t,a as o,E as l,a6 as h}from"./chunks/framework.CCKCzdWs.js";const d="/screenshots/run-trend-marker-tooltip.png",v=JSON.parse('{"title":"Timeline markers","description":"Deploys and infrastructure changes drawn on the trend charts, so a step change in pass rate or duration has a visible cause.","frontmatter":{"title":"Timeline markers","description":"Deploys and infrastructure changes drawn on the trend charts, so a step change in pass rate or duration has a visible cause.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/timeline-markers.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/timeline-markers.html"}],["meta",{"property":"og:title","content":"Timeline markers | Piwi for Playwright"}],["meta",{"property":"og:description","content":"Deploys and infrastructure changes drawn on the trend charts, so a step change in pass rate or duration has a visible cause."}]]},"headers":[],"relativePath":"features/timeline-markers.md","filePath":"features/timeline-markers.md","lastUpdated":1795125704000}'),p={name:"features/timeline-markers.md"};function c(k,e,m,u,g,y){const a=n("Needs");return r(),i("div",null,[e[0]||(e[0]=t("h1",{id:"timeline-markers",tabindex:"-1"},[o("Timeline markers "),t("a",{class:"header-anchor",href:"#timeline-markers","aria-label":'Permalink to "Timeline markers"'},"​")],-1)),l(a,{reporter:""}),e[1]||(e[1]=h('<p>Timeline markers let you record <strong>dated events</strong> against a project — a deploy, a config change, an infrastructure migration, a dependency bump, an incident — and see them overlaid as vertical lines on the analytics trend charts. When a pass-rate drop or a performance regression lines up with a marker, you have your prime suspect: &quot;the slowdown started the day we switched CI runners&quot;.</p><h2 id="what-a-marker-is" tabindex="-1">What a marker is <a class="header-anchor" href="#what-a-marker-is" aria-label="Permalink to &quot;What a marker is&quot;">​</a></h2><p>Each marker belongs to one project and carries:</p><ul><li><strong>Label</strong> — a short title (e.g. <em>Migrated CI to ARM runners</em>).</li><li><strong>Date &amp; time</strong> — when the event happened; this is where the line is drawn.</li><li><strong>Category</strong> — one of <code>deploy</code>, <code>config</code>, <code>infra</code>, <code>incident</code>, <code>release</code>, or a generic <code>event</code>. The category sets the marker&#39;s icon and color.</li><li><strong>Environment</strong> <em>(optional)</em> — one of the project&#39;s <a href="./environments.html">environments</a>, picked from its list. Leave it empty to apply to all environments. Through the API, <code>environment</code> names one by its key, an alias or a run&#39;s label, resolved as a run&#39;s label is.</li><li><strong>Commit</strong> <em>(optional, <code>deploy</code> markers)</em> — the application&#39;s commit the deploy put in place, 7 to 40 hexadecimal characters. A run of a <a href="./environments.html">deployed environment</a> that started after the marker ran against that commit, unless its server reported its own.</li><li><strong>Description</strong> <em>(optional)</em> — free-text detail.</li><li><strong>Run</strong> <em>(optional, API only)</em> — the id of one of the project&#39;s runs the event belongs to.</li></ul><h2 id="where-markers-show-up" tabindex="-1">Where markers show up <a class="header-anchor" href="#where-markers-show-up" aria-label="Permalink to &quot;Where markers show up&quot;">​</a></h2><figure><img src="'+d+`" alt="A project&#39;s Run trend with markers drawn as dashed vertical lines, one hovered: a Release marker named v2.3.0 with its date, environments and description"><figcaption>Markers on the Run trend; hovering one shows its details.</figcaption></figure><ul><li><strong>Project charts</strong> — the <strong>Run trend</strong> and <strong>Performance trend</strong> charts render each marker as a dashed vertical line with a colored flag handle. Hover the line or its flag for the marker&#39;s details (category, label, date, environment, a deploy&#39;s short commit, linked run, description); click it to open the marker in the <strong>Markers</strong> panel, in its edit form when you can edit markers.</li><li><strong>Markers panel</strong> — a <strong>Markers</strong> button beside the <strong>Run trend</strong> chart (on the project&#39;s Runs tab) opens a panel listing the project&#39;s markers, newest first. <strong>Add marker</strong> and each marker&#39;s edit button open the form in the panel itself; <strong>Delete</strong> is on each marker and in the edit form.</li><li><strong>Test-case history</strong> — a single test&#39;s duration history chart shows the same markers, so you can tell whether an event affected that specific test. Clicking one opens it in the project&#39;s <strong>Markers</strong> panel.</li><li><strong>Analytics charts</strong> — the trend charts of the <a href="./analytics.html">analytics page</a> draw the markers too, with the same details on hover: every marker with one project in scope; across projects only <code>release</code>, <code>infra</code> and <code>incident</code> markers, each labeled with its project. The <strong>Timeline markers</strong> widget lists a period&#39;s markers, and the analytics periods <em>Since a marker</em> and <em>Release cycle</em> start from them.</li><li><strong>Run detail</strong> — a run shows an <strong>&quot;After: …&quot;</strong> chip for the nearest preceding marker of its environment, or of all environments, so a single run tells you which event it followed.</li></ul><h2 id="environment-scoping" tabindex="-1">Environment scoping <a class="header-anchor" href="#environment-scoping" aria-label="Permalink to &quot;Environment scoping&quot;">​</a></h2><p>Markers tie into the project&#39;s existing <strong>environment filter</strong>. When you filter the project view to one or more environments, the charts show only markers of the selected environment(s) plus any global (no-environment) markers. This keeps a staging-only event from cluttering your production view. The analytics charts follow each project&#39;s environments the same way: with none picked, a project with a <a href="./environments.html#default-environment">default environment</a> shows that environment&#39;s markers and the global ones, unless <strong>All environments</strong> is on. A marker belongs to an environment as a run does: a marker written for <code>stg</code>, an alias of Staging, shows under Staging, and so does the analytics period&#39;s count of markers.</p><p>A marker keeps the label it was written with and the environment that label resolved to. Deleting the environment leaves the marker its label, matched as text.</p><h2 id="who-can-edit-markers" tabindex="-1">Who can edit markers <a class="header-anchor" href="#who-can-edit-markers" aria-label="Permalink to &quot;Who can edit markers&quot;">​</a></h2><p>Reading markers is available to anyone who can read the project. Creating, editing, and deleting them requires the <strong>Contributor</strong> role or above on the project, or an administrator (<a href="/operate/project-access.html#what-each-role-can-do">roles</a>). (When authentication is disabled, everyone can edit.)</p><h2 id="automatic-markers" tabindex="-1">Automatic markers <a class="header-anchor" href="#automatic-markers" aria-label="Permalink to &quot;Automatic markers&quot;">​</a></h2><p>Piwi can create markers for you when a run&#39;s tooling changes. On each finished run it compares the run against the previous run <strong>in the same environment</strong> (the environment its label resolved to, so <code>stg</code> and <code>staging</code> runs of Staging are one lineage) and, when the <strong>Playwright version</strong> or <strong>reporter version</strong> changed, adds an <code>auto</code> marker (category <code>config</code>) at that run&#39;s time — for example <em>Playwright 1.49.0 → 1.50.0</em>. Auto markers are labeled with a small sparkle icon and can be edited or deleted like any other.</p><p>When a run&#39;s <a href="./run-environment.html">environment</a> differs from the previous run on the same branch and in the same environment, it gets one <code>auto</code> marker per kind of change, labeled with the fields that changed: its runner or a browser (category <code>infra</code>), or a server under test (category <code>config</code>). A kind either run did not record counts as no change. A project that declines the Timeline markers <a href="/operate/capabilities.html">capability</a> gets none of these.</p><p>A run flagged as an <a href="./environment-incidents.html">environment incident</a> gets an <code>auto</code> marker in the <code>incident</code> category, linked to the run.</p><p>This is enabled by default. Set <code>PIWI_AUTO_MARKERS=false</code> to turn all three off. See the <a href="/reference/configuration.html">configuration reference</a>.</p><h2 id="release-markers-keep-their-run" tabindex="-1">Release markers keep their run <a class="header-anchor" href="#release-markers-keep-their-run" aria-label="Permalink to &quot;Release markers keep their run&quot;">​</a></h2><p>A <code>release</code> marker linked to a run keeps that run forever: <a href="/operate/storage.html#keeping-runs-forever">data retention</a> never deletes it, and the marker&#39;s label becomes the reason shown on the run. Deleting the marker, or changing its category to anything but <code>release</code>, releases the run again — unless someone kept it by hand or the reporter kept it at ingest, in which case the keep stays.</p><p>From CI, create the marker after the test step with the run id the reporter writes to its outputs (<code>piwi_run_id</code> on GitHub Actions, see <a href="/guide/ci.html#getting-the-run-url-back-out-of-ci">CI → Getting the run URL back out</a>):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PIWI_DASHBOARD_URL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/api/projects/&lt;projectId&gt;/markers&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PIWI_API_KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;label&quot;:&quot;v2.3.1&quot;,&quot;category&quot;:&quot;release&quot;,&quot;occurredAt&quot;:&quot;2026-09-24T12:00:00Z&quot;,&quot;runId&quot;:1234}&#39;</span></span></code></pre></div><h2 id="recording-deploys-from-ci" tabindex="-1">Recording deploys from CI <a class="header-anchor" href="#recording-deploys-from-ci" aria-label="Permalink to &quot;Recording deploys from CI&quot;">​</a></h2><p>A deploy pipeline records each deploy as a <code>deploy</code> marker that names the environment by its key and the commit it deployed. A run of that <a href="./environments.html">deployed environment</a> that starts after it reads its application at that commit, unless its server reports its own through an <a href="/guide/backend-logs.html#server-environment">instrumentation package</a>. Instrumentation is off in production by default, so production relies on these markers. The step runs after the deploy, with the project&#39;s id and an API key whose owner can add markers on the project (Contributor and above, <code>marker:write</code>), kept as a CI secret.</p><p>On GitHub Actions, after the deploy step:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">- </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Record the deploy in Piwi</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  env</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    PIWI_DASHBOARD_URL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\${{ vars.PIWI_DASHBOARD_URL }}</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    PIWI_API_KEY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\${{ secrets.PIWI_API_KEY }}</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  shell</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">bash</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;-</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    curl --fail --show-error -X POST &quot;$PIWI_DASHBOARD_URL/api/projects/12/markers&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    -H &quot;Authorization: Bearer $PIWI_API_KEY&quot; -H &quot;Content-Type: application/json&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    -d &quot;{\\&quot;label\\&quot;:\\&quot;Deploy to staging\\&quot;,\\&quot;category\\&quot;:\\&quot;deploy\\&quot;,\\&quot;environment\\&quot;:\\&quot;staging\\&quot;,\\&quot;commit\\&quot;:\\&quot;$GITHUB_SHA\\&quot;,\\&quot;occurredAt\\&quot;:\\&quot;$(date -u +%FT%TZ)\\&quot;}&quot;</span></span></code></pre></div><p>On GitLab CI, in the deploy job, with <code>PIWI_DASHBOARD_URL</code> and <code>PIWI_API_KEY</code> as masked CI/CD variables:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">deploy-staging</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  stage</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">deploy</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  script</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">./deploy.sh staging</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;-</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      curl --fail --show-error -X POST &quot;$PIWI_DASHBOARD_URL/api/projects/12/markers&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      -H &quot;Authorization: Bearer $PIWI_API_KEY&quot; -H &quot;Content-Type: application/json&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      -d &quot;{\\&quot;label\\&quot;:\\&quot;Deploy to staging\\&quot;,\\&quot;category\\&quot;:\\&quot;deploy\\&quot;,\\&quot;environment\\&quot;:\\&quot;staging\\&quot;,\\&quot;commit\\&quot;:\\&quot;$CI_COMMIT_SHA\\&quot;,\\&quot;occurredAt\\&quot;:\\&quot;$(date -u +%FT%TZ)\\&quot;}&quot;</span></span></code></pre></div><p>The commit is the pipeline&#39;s own, since the application lives in the tests&#39; repository. A commit that is not 7 to 40 hexadecimal characters is refused. <a href="./reuse-forecast.html#skipping-reusable-tests">Pass reuse</a> reads these markers too: a deployed environment&#39;s passes stand in only for runs against the commit deployed now.</p><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><p>Markers can also be managed through the REST API. See the interactive <a href="https://piwitests.dev/demo/settings/api" target="_blank" rel="noreferrer">API docs</a> for request and response shapes.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/recipes/regression-or-flaky.html">Regression or flake?</a>: correlating a failure with a deploy</li><li><a href="./analytics.html">Analytics</a>: the trend charts the markers annotate</li></ul>`,32))])}const q=s(p,[["render",c]]);export{v as __pageData,q as default};
